using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddSingleton<Notepad>();

builder.Services.AddChatClient(chatBuilder => chatBuilder
    .UseOpenAIChatClient(
        Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddSingleton<ResearchAgentRunner>();

builder.Logging.SetMinimumLevel(LogLevel.Warning);

var host = builder.Build();

var runner = host.Services.GetRequiredService<ResearchAgentRunner>();
await runner.RunAsync(args);

// --- Research Agent Runner ---

sealed class ResearchAgentRunner(
    IChatClient chatClient,
    ResearchTools tools,
    Notepad notepad,
    ILogger<ResearchAgentRunner> logger)
{
    public async Task RunAsync(string[] args)
    {
        var topic = args.Length > 0
            ? string.Join(' ', args)
            : PromptForTopic();

        Console.WriteLine($"\n🔍 Researching: {topic}\n");

        var agent = new ChatClientAgent(
            chatClient,
            name: "ResearchAgent",
            description: "An AI agent that researches topics by searching the web and taking notes.",
            instructions: """
                You are a research assistant. Your goal is to thoroughly research the given topic.

                Follow this workflow:
                1. Search the web for the topic to find relevant information.
                2. Take notes on key findings using the note-taking tool.
                3. Search for additional angles or subtopics to deepen your understanding.
                4. Take more notes as you discover new information.
                5. After gathering enough information (at least 3-4 searches), compile your notes
                   and provide a comprehensive summary.

                Always use the tools available to you. Be thorough but concise in your notes.
                """,
            tools:
            [
                AIFunctionFactory.Create(tools.SearchWebAsync),
                AIFunctionFactory.Create(tools.TakeNote),
                AIFunctionFactory.Create(tools.GetAllNotes),
            ]);

        agent.ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
        };

        var session = await agent.CreateSessionAsync();
        var runOptions = new ChatClientAgentRunOptions(new ChatOptions())
        {
            ChatOptions = { MaxOutputTokens = 2048 },
        };

        var response = await agent.RunAsync(
            $"Research the following topic and provide a comprehensive summary: {topic}",
            session,
            runOptions);

        Console.WriteLine("\n══════════════════════════════════════");
        Console.WriteLine("📋 RESEARCH SUMMARY");
        Console.WriteLine("══════════════════════════════════════\n");
        Console.WriteLine(response.Text);

        if (notepad.Notes.Count > 0)
        {
            Console.WriteLine("\n──────────────────────────────────────");
            Console.WriteLine("📝 COLLECTED NOTES");
            Console.WriteLine("──────────────────────────────────────");
            foreach (var note in notepad.Notes)
            {
                Console.WriteLine($"\n[{note.Category}] {note.Content}");
            }
        }

        Console.WriteLine();
        logger.LogInformation("Research completed. Total notes: {Count}", notepad.Notes.Count);
    }

    private static string PromptForTopic()
    {
        Console.Write("Enter a research topic: ");
        var topic = Console.ReadLine()?.Trim();
        if (string.IsNullOrWhiteSpace(topic))
        {
            Console.WriteLine("No topic provided. Exiting.");
            Environment.Exit(1);
        }

        return topic;
    }
}

// --- Tools ---

sealed class ResearchTools(Notepad notepad, ILogger<ResearchTools> logger)
{
    private static readonly HttpClient s_httpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Searches the web for information on a query. Returns a list of search results with titles, snippets, and URLs.")]
    public async Task<IReadOnlyList<SearchResult>> SearchWebAsync(
        [Description("The search query to look up")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);
        logger.LogInformation("Searching web for: {Query}", query);
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            // Use DuckDuckGo Instant Answer API (no API key required)
            var encodedQuery = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";

            var json = await s_httpClient.GetFromJsonAsync<JsonElement>(url);
            var results = new List<SearchResult>();

            // Extract abstract/answer
            var abstractText = json.GetProperty("Abstract").GetString();
            var abstractUrl = json.GetProperty("AbstractURL").GetString();
            var abstractSource = json.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add(new SearchResult(
                    abstractSource ?? "Summary",
                    abstractText,
                    abstractUrl ?? ""));
            }

            // Extract related topics
            if (json.TryGetProperty("RelatedTopics", out var relatedTopics))
            {
                foreach (var topic in relatedTopics.EnumerateArray())
                {
                    if (results.Count >= maxResults) break;

                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;

                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.Add(new SearchResult(
                            text.Length > 80 ? text[..80] + "..." : text,
                            text,
                            firstUrl ?? ""));
                    }
                }
            }

            // Extract answer if available
            var answer = json.GetProperty("Answer").GetString();
            if (!string.IsNullOrWhiteSpace(answer) && results.Count == 0)
            {
                results.Add(new SearchResult("Direct Answer", answer, ""));
            }

            if (results.Count == 0)
            {
                results.Add(new SearchResult(
                    "No results",
                    $"No direct results found for '{query}'. Try rephrasing or breaking down the query.",
                    ""));
            }

            Console.WriteLine($"  ✅ Found {results.Count} result(s)");
            return results;
        }
        catch (Exception ex)
        {
            logger.LogWarning(ex, "Web search failed for query: {Query}", query);
            return [new SearchResult("Error", $"Search failed: {ex.Message}. Try a different query.", "")];
        }
    }

    [Description("Takes a research note with a category label. Use this to record important findings during research.")]
    public string TakeNote(
        [Description("The content of the note")] string content,
        [Description("Category for the note (e.g., 'Key Finding', 'Definition', 'Statistic', 'Source')")] string category = "General")
    {
        notepad.AddNote(content, category);
        Console.WriteLine($"  📝 Note taken: [{category}]");
        return $"Note recorded under '{category}': {content[..Math.Min(content.Length, 60)]}...";
    }

    [Description("Retrieves all notes taken so far. Use this to review what you've learned before writing a summary.")]
    public IReadOnlyList<Note> GetAllNotes()
    {
        Console.WriteLine($"  📋 Reviewing {notepad.Notes.Count} note(s)");
        return notepad.Notes;
    }
}

// --- Models ---

record SearchResult(string Title, string Snippet, string Url);

record Note(string Content, string Category, DateTime Timestamp);

sealed class Notepad
{
    private readonly List<Note> _notes = [];

    public IReadOnlyList<Note> Notes => _notes;

    public void AddNote(string content, string category)
    {
        _notes.Add(new Note(content, category, DateTime.UtcNow));
    }
}

