34. // --- Research Agent Runner ---
35. 
36. sealed class ResearchAgentRunner(
37.     IChatClient chatClient,
38.     ResearchTools tools,
39.     Notepad notepad,
40.     ILogger<ResearchAgentRunner> logger)
41. {
42.     public async Task RunAsync(string[] args)
43.     {
44.         var topic = args.Length > 0
45.             ? string.Join(' ', args)
46.             : PromptForTopic();
47. 
48.         Console.WriteLine($"\n🔍 Researching: {topic}\n");
49. 
50.         var agent = new ChatClientAgent(
51.             chatClient,
52.             name: "ResearchAgent",
53.             description: "An AI agent that researches topics by searching the web and taking notes.",
54.             instructions: """
55.                 You are a research assistant. Your goal is to thoroughly research the given topic.
56. 
57.                 Follow this workflow:
58.                 1. Search the web for the topic to find relevant information.
59.                 2. Take notes on key findings using the note-taking tool.
60.                 3. Search for additional angles or subtopics to deepen your understanding.
61.                 4. Take more notes as you discover new information.
62.                 5. After gathering enough information (at least 3-4 searches), compile your notes
63.                    and provide a comprehensive summary.
64. 
65.                 Always use the tools available to you. Be thorough but concise in your notes.
66.                 """,
67.             tools:
68.             [
69.                 AIFunctionFactory.Create(tools.SearchWebAsync),
70.                 AIFunctionFactory.Create(tools.TakeNote),
71.                 AIFunctionFactory.Create(tools.GetAllNotes),
72.             ]);
73. 
74.         var session = await agent.CreateSessionAsync();
75.         var runOptions = new ChatClientAgentRunOptions(new ChatOptions
76.         {
77.             Temperature = 0f,
78.             MaxOutputTokens = 2048,
79.         });
80. 
81.         var response = await agent.RunAsync(
82.             $"Research the following topic and provide a comprehensive summary: {topic}",
83.             session,
84.             runOptions);
85. 
86.         Console.WriteLine("\n══════════════════════════════════════");
87.         Console.WriteLine("📋 RESEARCH SUMMARY");
88.         Console.WriteLine("══════════════════════════════════════\n");
89.         Console.WriteLine(response.Text);
90. 
91.         if (notepad.Notes.Count > 0)
92.         {
93.             Console.WriteLine("\n──────────────────────────────────────");
94.             Console.WriteLine("📝 COLLECTED NOTES");
95.             Console.WriteLine("──────────────────────────────────────");
96.             foreach (var note in notepad.Notes)
97.             {
98.                 Console.WriteLine($"\n[{note.Category}] {note.Content}");
99.             }
100.         }
101. 
102.         Console.WriteLine();
103.         logger.LogInformation("Research completed. Total notes: {Count}", notepad.Notes.Count);
104.     }
105. 
106.     private static string PromptForTopic()
107.     {
108.         Console.Write("Enter a research topic: ");
109.         var topic = Console.ReadLine()?.Trim();
110.         if (string.IsNullOrWhiteSpace(topic))
111.         {
112.             Console.WriteLine("No topic provided. Exiting.");
113.             Environment.Exit(1);
114.         }
115. 
116.         return topic;
117.     }
118. }
119. 
120. // --- Tools ---
121. 
122. sealed class ResearchTools(Notepad notepad, ILogger<ResearchTools> logger)
123. {
124.     private static readonly HttpClient s_httpClient = new()
125.     {
126.         Timeout = TimeSpan.FromSeconds(15),
127.     };
128. 
129.     [Description("Searches the web for information on a query. Returns a list of search results with titles, snippets, and URLs.")]
130.     public async Task<IReadOnlyList<SearchResult>> SearchWebAsync(
131.         [Description("The search query to look up")] string query,
132.         [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
133.     {
134.         maxResults = Math.Clamp(maxResults, 1, 10);
135.         logger.LogInformation("Searching web for: {Query}", query);
136.         Console.WriteLine($"  🌐 Searching: \"{query}\"");
137. 
138.         try
139.         {
140.             // Use DuckDuckGo Instant Answer API (no API key required)
141.             var encodedQuery = Uri.EscapeDataString(query);
142.             var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";
143. 
144.             var json = await s_httpClient.GetFromJsonAsync<JsonElement>(url);
145.             var results = new List<SearchResult>();
146. 
147.             // Extract abstract/answer
148.             var abstractText = json.GetProperty("Abstract").GetString();
149.             var abstractUrl = json.GetProperty("AbstractURL").GetString();
150.             var abstractSource = json.GetProperty("AbstractSource").GetString();
151.             if (!string.IsNullOrWhiteSpace(abstractText))
152.             {
153.                 results.Add(new SearchResult(
154.                     abstractSource ?? "Summary",
155.                     abstractText,
156.                     abstractUrl ?? ""));
157.             }
158. 
159.             // Extract related topics
160.             if (json.TryGetProperty("RelatedTopics", out var relatedTopics))
161.             {
162.                 foreach (var topic in relatedTopics.EnumerateArray())
163.                 {
164.                     if (results.Count >= maxResults) break;
165. 
166.                     var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
167.                     var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
168. 
169.                     if (!string.IsNullOrWhiteSpace(text))
170.                     {
171.                         results.Add(new SearchResult(
172.                             text.Length > 80 ? text[..80] + "..." : text,
173.                             text,
174.                             firstUrl ?? ""));
175.                     }
176.                 }
177.             }
178. 
179.             // Extract answer if available
180.             var answer = json.GetProperty("Answer").GetString();
181.             if (!string.IsNullOrWhiteSpace(answer) && results.Count == 0)
182.             {
183.                 results.Add(new SearchResult("Direct Answer", answer, ""));
184.             }
185. 
186.             if (results.Count == 0)
187.             {
188.                 results.Add(new SearchResult(
189.                     "No results",
190.                     $"No direct results found for '{query}'. Try rephrasing or breaking down the query.",
191.                     ""));
192.             }
193. 
194.             Console.WriteLine($"  ✅ Found {results.Count} result(s)");
195.             return results;
196.         }
197.         catch (Exception ex)
198.         {
199.             logger.LogWarning(ex, "Web search failed for query: {Query}", query);
200.             return [new SearchResult("Error", $"Search failed: {ex.Message}. Try a different query.", "")];
201.         }
202.     }
203. 
204.     [Description("Takes a research note with a category label. Use this to record important findings during research.")]
205.     public string TakeNote(
206.         [Description("The content of the note")] string content,
207.         [Description("Category for the note (e.g., 'Key Finding', 'Definition', 'Statistic', 'Source')")] string category = "General")
208.     {
209.         notepad.AddNote(content, category);
210.         Console.WriteLine($"  📝 Note taken: [{category}]");
211.         return $"Note recorded under '{category}': {content[..Math.Min(content.Length, 60)]}...";
212.     }
213. 
214.     [Description("Retrieves all notes taken so far. Use this to review what you've learned before writing a summary.")]
215.     public IReadOnlyList<Note> GetAllNotes()
216.     {
217.         Console.WriteLine($"  📋 Reviewing {notepad.Notes.Count} note(s)");
218.         return notepad.Notes;
219.     }
220. }
221. 
222. // --- Models ---
223. 
224. record SearchResult(string Title, string Snippet, string Url);
225. 
226. record Note(string Content, string Category, DateTime Timestamp);
227. 
228. sealed class Notepad
229. {
230.     private readonly List<Note> _notes = [];
231. 
232.     public IReadOnlyList<Note> Notes => _notes;
233. 
234.     public void AddNote(string content, string category)
235.     {
236.         _notes.Add(new Note(content, category, DateTime.UtcNow));
237.     }
238. }
